function showTownLayerTest(){
 const s=F.readSave(),states=F.townLayerStates(s),groups=[],preset=F.townLayerTestPreset(s);
 for(const g of (F.TOWN_LAYER_GROUPS||[]))if(states.some(x=>x.def.group===g))groups.push(g);
 for(const x of states)if(!groups.includes(x.def.group))groups.push(x.def.group||'その他');
 const route=F.townRoute(s),presetName={auto:'全部 自動',custom:'個別指定',off:'全部 OFF（初期）',max:'全部 ON（完成）',raw:'生レイヤー確認'}[preset]||preset;
 let html=`<h2>🧪 TEST レイヤー指定</h2><p>現在：<b>${esc(presetName)}</b>。<b>全部ONは「完成した町」</b>として表示し、道Lv1/Lv2など同系統の段階画像は排他制御します。素材を本当に全重ねしたい場合だけ「生レイヤー確認」を使います。実データは変更しません。</p><div class="layerLegend"><span>自動＝通常ゲーム判定</span><span>ON＝強制表示</span><span>OFF＝強制非表示</span><span>排他＝同グループは1段階だけ</span></div>`;
 for(const g of groups){html+=`<h3 class="layerGroupTitle">${esc(g)}</h3><div class="layerTestList">`;for(const x of states.filter(y=>y.def.group===g)){const d=x.def,auto=x.auto?'ON':'OFF',eff=x.effective?'表示':'非表示',ex=d.exclusiveGroup?` / 排他:${d.exclusiveGroup} Lv${d.rank||0}`:'';html+=`<div class="layerTestRow"><div class="layerTestName"><b>${esc(d.icon||'▫️')} ${esc(d.label||d.id)}</b><small>描画帯 ${esc(d.band||'-')} / 通常 ${auto} / 現在 ${eff}${ex}${x.suppressed?' / 排他で抑制':''}${d.locked?' / 固定':''}</small></div><div class="layerModeBtns">${d.locked?'<span class="layerLocked">固定ON</span>':['auto','on','off'].map(m=>`<button type="button" data-layer-id="${esc(d.id)}" data-layer-mode="${m}" class="${x.mode===m&&preset==='custom'?'on':''}">${m==='auto'?'自動':m.toUpperCase()}</button>`).join('')}</div></div>`}html+='</div>'}
 modal(html,[
  {label:'全部 自動',close:false,fn:()=>{F.setAllTownLayerTestModes('auto');closeModal();renderAll();showTownLayerTest()}},
  {label:'全部 OFF（初期）',close:false,fn:()=>{F.setAllTownLayerTestModes('off');closeModal();renderAll();showTownLayerTest()}},
  {label:'全部 ON（完成）',className:'cmdBtn primary',close:false,fn:()=>{F.setAllTownLayerTestModes('on');closeModal();renderAll();showTownLayerTest()}},
  {label:'⚠ 生レイヤー確認',className:'cmdBtn warn',close:false,fn:()=>{F.setAllTownLayerTestModes('raw');closeModal();renderAll();showTownLayerTest()}},
  {label:'閉じる'}
 ]);
 document.querySelectorAll('[data-layer-id][data-layer-mode]').forEach(b=>b.onclick=()=>{try{F.setTownLayerTestMode(b.dataset.layerId,b.dataset.layerMode);closeModal();renderAll();showTownLayerTest()}catch(e){toast(e.message)}});
}

function showDevelopment(){const s=F.readSave(),opts=F.townOptions(s),projects=F.townProjects?.(s)||[],route=F.townRoute(s),routeName={standard:"まだ方向未定",commerce:"商業",forge:"鍛冶",life:"生活",adventure:"冒険"}[route]||route;let html=`<h2>🏗️ 町を発展させる</h2><p>現在 <b>${Number(s.development.points)||0}pt</b> ／ 育ち方：<b>${esc(routeName)}</b>。施設は選んだ瞬間には完成せず、予定地→資材搬入→骨組み→仕上げ→完成と進みます。</p>`;if(projects.length){html+='<h3>🚧 工事中</h3><div class="choiceGrid">';for(const pr of projects){const def=(F.FACILITY_DEFS||[]).find(d=>d.id===pr.facilityId),ph=F.constructionPhase(pr),pct=Math.round((ph?.progress||0)*100);html+=`<div class="choiceCard" style="grid-template-columns:auto 1fr"><div style="font-size:30px">${ph?.icon||'🏗️'}</div><span><b>${esc(def?.name||pr.facilityId)} Lv${pr.fromLevel} → Lv${pr.targetLevel}</b><small>${esc(ph?.label||'工事中')} / 進捗目安 ${pct}%<br>次の日・次の帰還で工事が1段階進みます。</small></span></div>`}html+='</div>'}html+='<h3>次に始められる工事</h3><div class="choiceGrid">';for(const o of opts){const state=o.available?'着工できます':`${o.need}ptで解放`;html+=`<button class="choiceCard" data-dev="${esc(o.id)}" ${!o.available?'disabled':''}><div style="font-size:30px">${o.icon}</div><span><b>${esc(o.name)}</b><small>${esc(o.desc)}<br>完成まで複数段階あります。</small><div class="badge">${state}</div></span></button>`}if(!opts.length)html+='<p>現在、新しく着工できる施設はありません。</p>';html+='</div>';const actions=[{label:'閉じる'}];if(window.FRENDA_TEST?.active){if(projects.length)actions.unshift({label:'🧪 工事を1段階進める',className:'cmdBtn primary',close:false,fn:()=>{F.advanceTownConstruction(1);closeModal();renderAll();showDevelopment()}});actions.unshift({label:'🧪 +2pt',className:'cmdBtn warn',close:false,fn:()=>{F.addDevelopmentPoints(2);closeModal();showDevelopment();renderAll()}})}modal(html,actions);document.querySelectorAll('[data-dev]').forEach(b=>b.onclick=()=>{try{F.applyTownDevelopment(b.dataset.dev);closeModal();toast('工事を開始しました');renderAll();showDevelopment()}catch(e){toast(e.message)}})}
function showPartnerModal(){const s=F.readSave(),list=F.eligibleCompanions?.(s)||[],trial=F.usingTrialPartners?.(),shown=list.slice(0,120);let html=`<h2>🐾 町のポケモン</h2><p>所持ポケモンはダンジョンには同行せず、<b>町の施設・依頼・発展</b>で活躍させます。${trial?'<br><small>TEST環境では確認用候補も含みます。</small>':''}</p>`;if(shown.length){html+='<div class="partnerGrid">';for(const sp of shown){const access=F.companionAccess?.(sp,s)||{reasons:[]};html+=`<div class="partnerCard">${speciesAvatar(sp)}<span><b>${esc(sp.name)}</b><small>${esc([sp.type1,sp.type2].filter(Boolean).join(' / '))}</small><div><span class="badge">町で活躍予定</span>${access.reasons.slice(0,1).map(x=>`<span class="badge">${esc(x)}</span>`).join('')}</div></span></div>`}html+='</div>'}else html+='<p>所持連携されたポケモンはまだありません。</p>';html+='<p><small>施設への配属・得意分野の効果は次段階で実装します。</small></p>';modal(html,[{label:'閉じる'}])}
function equipmentStatText(d){if(!d)return'';const a=[];if(Number(d.attack))a.push(`攻撃+${Number(d.attack)}`);if(Number(d.defense))a.push(`防御+${Number(d.defense)}`);if(Number(d.hp))a.push(`最大HP+${Number(d.hp)}`);if(d.weapon){const w=d.weapon;a.push(`${w.label||'武器'}・射程${Number(w.range)||1}`);a.push(`命中${Math.round((Number(w.accuracy)||.9)*100)}%`)}if(Number(d.accuracyBonus))a.push(`命中+${Math.round(Number(d.accuracyBonus)*100)}%`);if(Number(d.criticalBonus))a.push(`急所+${Math.round(Number(d.criticalBonus)*100)}%`);if(Number(d.damageReduction))a.push(`被ダメ-${Number(d.damageReduction)}`);if(Number(d.foodSaveEvery))a.push(`満腹度減少を時々抑える`);return a.join(' / ')||'補正なし'}
function equipmentDelta(label,from,to){from=Number(from)||0;to=Number(to)||0;const d=to-from;if(!d)return `${label} ${from} → ${to}`;return `${label} ${from} → ${to} ${d>0?'▲':'▼'}${Math.abs(d)}`}
function equipmentCompareText(candidate,current){if(!candidate)return'';const cur=current||{};if(candidate.slot==='weapon')return equipmentDelta('攻撃',cur.attack,candidate.attack);if(candidate.slot==='armor')return [equipmentDelta('防御',cur.defense,candidate.defense),Number(candidate.hp)!==Number(cur.hp||0)?equipmentDelta('最大HP',cur.hp,candidate.hp):''].filter(Boolean).join(' / ');return [equipmentDelta('攻撃',cur.attack,candidate.attack),equipmentDelta('防御',cur.defense,candidate.defense),equipmentDelta('最大HP',cur.hp,candidate.hp)].filter((x,i)=>i===2||Number(candidate[['attack','defense'][i]])!==Number(cur[['attack','defense'][i]]||0)).join(' / ')}
function equipmentDisplayView(inst){return inst?.identified===false?(F.equipmentInstancePreview?.(inst)||F.equipmentInstanceView?.(inst)):F.equipmentInstanceView?.(inst)}
function equipmentKnowledgeText(inst,d){if(inst?.identified===false)return '❓ 未鑑定：特殊効果・呪いは装備すると判明';const a=[];if(d?.traitText)a.push(`✨ ${d.trait?.name||'特殊効果'}：${d.traitText}`);if(d?.curseText)a.push(`💀 ${d.curseText}`);return a.join(' / ')}
function showEquipmentModal(){
 const s=F.readSave(),run=F.run?.active?F.run:null,baseStats=run?{attack:run.playerAttack,defense:run.playerDefense,hp:run.playerMaxHp}:null,bonus=F.equipmentStats?.(s)||{attack:0,defense:0,hp:0},all=run?(F.dungeonCarriedEquipment?.(run)||[]):(F.equipmentOwnedInstances?.(s)||[]),foundSet=new Set(run?.foundEquipmentUids||[]);
 let html=`<h2>⚔️ 装備</h2><p>${run?'拾った装備は未鑑定の場合があります。装備すると特殊効果・呪いが判明し、装備変更は1ターン使います。':'装備は1個ずつ個体管理。未鑑定品は装備を試すと性質が判明します。'}<br><b>${run?`攻撃 ${baseStats.attack} / 防御 ${baseStats.defense} / 最大HP ${baseStats.hp}`:`装備補正：攻撃+${bonus.attack} / 防御+${bonus.defense} / 最大HP+${bonus.hp}`}</b></p>`;
 for(const slot of (F.EQUIPMENT_SLOTS||[])){
  const currentUid=run?run.equippedUids?.[slot.id]:s.equipment?.equippedUids?.[slot.id],currentInst=all.find(x=>x.uid===currentUid)||(run?null:F.equipmentEquippedInstance?.(s,slot.id)),current=currentInst?F.equipmentInstanceView?.(currentInst):(run?F.dungeonEquippedView?.(run,slot.id):bonus.items?.[slot.id]);
  html+=`<h3>${slot.icon} ${esc(slot.label)}：${esc(current?.name||'なし')}</h3><div class="choiceGrid">`;
  const owned=all.filter(inst=>F.equipment?.(inst.defId)?.slot===slot.id);
  for(const inst of owned){
   const d=equipmentDisplayView(inst),actual=F.equipmentInstanceView?.(inst),on=currentUid===inst.uid,found=run&&foundSet.has(inst.uid),unknown=inst.identified===false,knownExtra=equipmentKnowledgeText(inst,actual),cmp=equipmentCompareText(d,current);
   const actionText=run&&!on?'タップで装備（1ターン）':(!run&&!on?(unknown?'タップで装備を試す（性質判明）':'タップで装備'):'');
   html+=`<button class="choiceCard ${on?'on':''}" ${run?`data-run-equip-uid="${esc(inst.uid)}"`:`data-equip-slot="${esc(slot.id)}" data-equip-uid="${esc(inst.uid)}"`} ${on?'disabled':''}><div>${equipmentVisualHtml(d,46)}</div><span><b>${esc(d?.name||inst.defId)}${on?' ✅':''}${found?' 🆕':''}${unknown?' ❓':''}</b><small>${esc(equipmentStatText(d))}<br><b>${esc(cmp)}</b>${knownExtra?`<br>${esc(knownExtra)}`:''}${actionText?`<br>${esc(actionText)}`:''}</small></span></button>`;
  }
  if(!owned.length)html+='<p><small>この種類の装備はありません。</small></p>';
  html+='</div>';
 }
 if(!run){
  const cursed=all.filter(inst=>inst.identified!==false&&inst.cursed);
  if(cursed.length)html+='<h3>📜 町でおはらい</h3><p><small>持ち帰った呪いは町で安全に解除できます。</small></p><div class="choiceGrid">'+cursed.map(inst=>{const d=F.equipmentInstanceView?.(inst);return `<button class="choiceCard" data-purify-equip-uid="${esc(inst.uid)}"><div>${equipmentVisualHtml(d,42)}</div><span><b>${esc(d?.name||inst.defId)}</b><small>タップして呪いを解く</small></span></button>`}).join('')+'</div>';
 }
 modal(html,[{label:'閉じる'}]);
 if(run){
  document.querySelectorAll('[data-run-equip-uid]').forEach(b=>b.onclick=()=>{const r=F.dungeonEquipItem?.(b.dataset.runEquipUid);if(r?.ok){closeModal();renderAll();if(r.cursed)toast('💀 呪われていた！ おはらいするまで外せません');else if(r.trait)toast(`✨ 特殊効果「${r.trait.name}」が判明！`);else toast(`${r.item.name}を装備しました`);if(F.run&&!F.run.active)runResultModal()}else if(r?.reason)toast(r.reason)})
 }else{
  document.querySelectorAll('[data-equip-uid]').forEach(b=>b.onclick=()=>{try{F.equipItem?.(b.dataset.equipSlot,b.dataset.equipUid);closeModal();toast('装備を変更しました');renderAll();showEquipmentModal()}catch(e){closeModal();renderAll();toast(e.message);showEquipmentModal()}});
  document.querySelectorAll('[data-purify-equip-uid]').forEach(b=>b.onclick=()=>{try{F.purifyOwnedEquipment?.(b.dataset.purifyEquipUid);closeModal();toast('📜 呪いを解きました');renderAll();showEquipmentModal()}catch(e){toast(e.message)}})
 }
}
function dungeonFacingLabel(face){return ({up:'上','up-right':'右上',right:'右','down-right':'右下',down:'下','down-left':'左下',left:'左','up-left':'左上'})[String(face||'down')]||'下'}
function showFacingModal(){const run=F.run;if(!run?.active){toast('探索中のみ使えます');return}const current=String(run.playerFacing||'down'),btn=(face,icon)=>`<button class="directionPadBtn ${current===face?'on':''}" data-facing="${face}" aria-label="${dungeonFacingLabel(face)}を向く"><b>${icon}</b><small>${dungeonFacingLabel(face)}</small></button>`;const html=`<h2>🧭 向きを変える</h2><p>現在の向き：<b>${esc(dungeonFacingLabel(current))}</b><br><small>8方向から選べます。移動せず、ターンも進みません。素振り・杖・投げる方向にも使われます。</small></p><div class="directionPad">${btn('up-left','↖')}${btn('up','↑')}${btn('up-right','↗')}${btn('left','←')}<button class="directionPadBtn center" data-facing-close="1"><b>●</b><small>閉じる</small></button>${btn('right','→')}${btn('down-left','↙')}${btn('down','↓')}${btn('down-right','↘')}</div>`;modal(html,[{label:'閉じる'}]);document.querySelectorAll('[data-facing]').forEach(b=>b.onclick=()=>{const face=b.dataset.facing;if(F.setDungeonFacing?.(face)){closeModal();renderAll();toast(`向きを${dungeonFacingLabel(face)}に変えました`)}});document.querySelector('[data-facing-close]')?.addEventListener('click',closeModal)}
function showStrengthModal(){const run=F.run;if(!run?.active){showEquipmentModal();return}const w=F.dungeonEquippedView?.(run,'weapon'),a=F.dungeonEquippedView?.(run,'armor'),c=F.dungeonEquippedView?.(run,'charm'),wp=F.weaponProfile?.(run)||{range:1,accuracy:.9,label:'武器'},bonus=(Number(c?.accuracyBonus)||0),extra=d=>[d?.traitText?`✨ ${esc(d.trait?.name||'特殊効果')}：${esc(d.traitText)}`:'',d?.curseText?`💀 ${esc(d.curseText)}`:''].filter(Boolean).join('<br>');modal(`<h2>💪 冒険者のつよさ</h2><p><b>Lv ${run.playerLv}</b><br>❤️ HP ${run.playerHp}/${run.playerMaxHp}<br>⚔️ 攻撃 ${run.playerAttack}<br>🛡️ 防御 ${run.playerDefense}<br>🍞 満腹度 ${run.fullness}/${run.fullnessMax}</p><p><b>武器：</b>${esc(w?.name||'なし')}<br>${esc(wp.label||'武器')} / 射程 ${wp.range} / 命中 ${Math.round(Math.min(.99,wp.accuracy+bonus)*100)}%<br><small>${esc(w?.desc||'')}${extra(w)?`<br>${extra(w)}`:''}</small></p><p><b>防具：</b>${esc(a?.name||'なし')}<br><small>${esc(a?.desc||'')}${extra(a)?`<br>${extra(a)}`:''}</small></p><p><b>お守り：</b>${esc(c?.name||'なし')}<br><small>${esc(c?.desc||'')}${extra(c)?`<br>${extra(c)}`:''}</small></p>`,[{label:'閉じる'}])}
